interface Renderer { circle(r: number): void }    // structural Implementor

abstract class Shape {                            // Abstraction
  protected constructor(protected readonly renderer: Renderer) {}
  abstract draw(): void
}

class Circle extends Shape {
  constructor(renderer: Renderer, private readonly radius: number) { super(renderer) }
  draw(): void { this.renderer.circle(this.radius) }
}
